 * The scanner. It turns UTF-8 source text into positioned tokens, or throws a
 * ScanError carrying the position and the reason of the first failure.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const isDigit = (c) => c >= '0' && c <= '9'
const isHex = (c) => isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
const isBin = (c) => c === '0' || c === '1'
const isOctal = (c) => c >= '0' && c <= '7'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
const isIdentStart = (c) => c !== undefined && (isLetter(c) || c === '_')
const isIdentPart = (c) => c !== undefined && (isLetter(c) || isDigit(c) || c === '_')

class Scanner {
  constructor(source) {
    // Positions and token text count code points, not UTF-16 units.
    this.chars = Array.from(source)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  get done() {
    return this.i >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  /** Consumes one code point, keeping the line and column in step with it. */
  advance() {
    const c = this.chars[this.i]
    this.i += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return c
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  textFrom(start) {
    return this.chars.slice(start, this.i).join('')
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipBlanksAndComments()
      if (this.done) return tokens
      tokens.push(this.scanToken())
    }
  }

  skipBlanksAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        while (!this.done && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      return
    }
  }

  /** Skips a `/* ... *\/` comment, allowing nesting; reports at the outermost. */
  skipBlockComment() {
    const line = this.line
    const column = this.column
    let depth = 0
    for (;;) {
      if (this.done) this.fail(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth += 1
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.advance()
    }
  }

  scanToken() {
    const line = this.line
    const column = this.column
    const c = this.peek()

    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(line, column)
    if (isIdentStart(c)) return this.scanWord(line, column)
    if (isDigit(c)) return this.scanNumber(line, column)
    if (c === '"') return this.scanString(line, column)

    const punct = this.scanPunct(line, column)
    if (punct) return punct

    this.advance()
    this.fail(line, column, `unexpected character ${c}`)
  }

  scanWord(line, column) {
    const start = this.i
    while (isIdentPart(this.peek())) this.advance()
    const text = this.textFrom(start)
    return { line, column, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', body: text }
  }

  /**
   * Reads a run of digits in which a `_` is only allowed between two digits.
   * Returns whether the run held at least one digit.
   */
  readDigitRun(accepts) {
    if (!this.peek() || !accepts(this.peek())) return false
    this.advance()
    for (;;) {
      const c = this.peek()
      if (c !== undefined && accepts(c)) {
        this.advance()
        continue
      }
      const next = this.peek(1)
      if (c === '_' && next !== undefined && accepts(next)) {
        this.advance()
        this.advance()
        continue
      }
      return true
    }
