      value += this.advance()
    }
  }

  /** Reads one escape sequence and returns the text it stands for. */
  scanEscape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.advance() // the backslash
    if (this.done) this.fail(stringLine, stringColumn, 'unterminated string')
    const c = this.peek()
    const bad = () => this.fail(line, column, `invalid escape \\${c}`)
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }

    if (Object.hasOwn(simple, c) && c !== undefined) {
      this.advance()
      return simple[c]
    }
    if (c === 'x') {
      const first = this.peek(1)
      const second = this.peek(2)
      if (first === undefined || second === undefined || !isHex(first) || !isHex(second)) bad()
      this.advance()
      this.advance()
      this.advance()
      return String.fromCodePoint(parseInt(first + second, 16))
    }
    if (c === 'u') {
      if (this.peek(1) !== '{') bad()
      let offset = 2
      let digits = ''
