      if (code > 0x10ffff) bad()
      for (let step = 0; step <= offset; step += 1) this.advance()
      return String.fromCodePoint(code)
    }
    bad()
  }

  scanRawString(line, column) {
    this.advance() // the `r`
    this.advance() // the opening quote
    let value = ''
    for (;;) {
      if (this.done) this.fail(line, column, 'unterminated string')
      const c = this.advance()
      if (c === '"') return { line, column, kind: 'rawstring', body: value }
      value += c
    }
  }

  scanPunct(line, column) {
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    const doubles = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
    const singles = '+-*/%=<>!(){}[],;.'
    if (doubles.includes(two)) {
      this.advance()
      this.advance()
      return { line, column, kind: 'punct', body: two }
    }
    const c = this.peek()
    if (c !== undefined && singles.includes(c)) {
      this.advance()
      return { line, column, kind: 'punct', body: c }
    }
    return null
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
