    .map((token) => {
      const body =
        token.kind === 'string' || token.kind === 'rawstring'
          ? JSON.stringify(token.body)
          : token.body
      return `${token.line}:${token.column} ${token.kind} ${body}\n`
    })
    .join('')
}

